\label{lem:stochastic domination}
 	Let $G$ be an infinite network and $\mathfrak{F}$ be a sample of OWUSF on $G$. For each $v\in V(G)$, let $\mathfrak{F}_v$ be an oriented $v$-WUSF of $G$. Suppose $K$ is a finite set of vertices of $G$ and define $F(K):=\bigcup_{u\in K}\mathfrak{F}(u,\infty)$ and $F_v(K):=\bigcup_{u\in K}\mathfrak{F}_v(u,\infty)$. Then for every $u\in K$ and every increasing event $\mathscr{A}\subset \{0,1\}^E$ we have 
 	\begin{equation}\label{eq:SD 1}
 	\mathbb{P}\left( \textnormal{past}_{\mathfrak{F}\backslash F(K)}(u)\in\mathscr{A}\mid F(K)\right)
 	\leq \mathbb{P}(\mathfrak{T}_u\in\mathscr{A})
 	\end{equation}
 	and similarly
 	\begin{equation}\label{eq:SD 2}
 	\mathbb{P}\left( \textnormal{past}_{\mathfrak{F}_v\backslash F_v(K)}(u)\in\mathscr{A}\mid F(K)\right)
 	\leq \mathbb{P}(\mathfrak{T}_u\in\mathscr{A}).
 	\end{equation}

\begin{equation}\label{eq:SD 1}
 	\mathbb{P}\left( \textnormal{past}_{\mathfrak{F}\backslash F(K)}(u)\in\mathscr{A}\mid F(K)\right)
 	\leq \mathbb{P}(\mathfrak{T}_u\in\mathscr{A})
 	\end{equation}

\begin{equation}\label{eq:SD 2}
 	\mathbb{P}\left( \textnormal{past}_{\mathfrak{F}_v\backslash F_v(K)}(u)\in\mathscr{A}\mid F(K)\right)
 	\leq \mathbb{P}(\mathfrak{T}_u\in\mathscr{A}).
 	\end{equation}

