\label{cor:large deviation for SRW on nonunimodular transitive graph}
 	Fix $x\in V(G)$ and suppose $\{X_n^x\}_{n\geq0}$ is a simple random walk on $G$ starting at $x$. Let $n\vee 1=\max\{ 1,n\}$ denote the maximum of $n$ and $1$.
  	Then 
 	\begin{equation}\label{eq: occupation times for srw on -n slab}
 	\mathbb{E}\left[\sum_{k=0}^{\infty}\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\right]\asymp 1
 	\ \textnormal{ and }\ 
 	\mathbb{E}\left[\sum_{k=0}^{\infty}k\cdot\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\right]\asymp n\vee 1.
 	\end{equation}



 	For an integer $n\geq0$, let $\tau_{-n}^x:=\sup\{k:X_k\in L_{-n}(x)\}$ be the last visit time of the slab $L_{-n}(x)$. Then there exist constants $c_1,c_2,c_3>0$ such that 
 	\begin{equation} \label{eq:tail probability for last visit time of SRW with a fixed level}
 	\mathbb{P}[\tau_{-n}^x\geq R]\leq c_1\exp(-c_2R),\ \ \forall \ R\geq c_3(n\vee 1).
 	\end{equation}

\begin{equation}\label{eq: occupation times for srw on -n slab}
 	\mathbb{E}\left[\sum_{k=0}^{\infty}\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\right]\asymp 1
 	\ \textnormal{ and }\ 
 	\mathbb{E}\left[\sum_{k=0}^{\infty}k\cdot\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\right]\asymp n\vee 1.
 	\end{equation}

\begin{equation} \label{eq:tail probability for last visit time of SRW with a fixed level}
 	\mathbb{P}[\tau_{-n}^x\geq R]\leq c_1\exp(-c_2R),\ \ \forall \ R\geq c_3(n\vee 1).
 	\end{equation}

	By the cocycle identity $\log \Delta(X_0^x,X_k^x)=\sum_{j=1}^{k}\log \Delta(X_{j-1}^x,X_j^x)$. 
	Since $\log \Delta(X_{j-1}^x,X_j^x)$ are independent, identically distributed random variables, the law of large numbers and Lemma \ref{lem:expectation for SRW on nonunimodular transitive graph}  then imply that 
	\begin{equation}\label{eq: LLN for srw}
	\frac{1}{k}\log \Delta(X_0^x,X_k^x)=\frac{1}{k}\sum_{j=1}^{k}\log \Delta(X_{j-1}^x,X_j^x)\rightarrow
	\mathbb{E}[\log\Delta(X_0^x,X_1^x)]<0\ \mathrm{a.s.}
	\end{equation}
	Also there exists a constant $c\in(0,1)$ such that 
	\begin{equation} \label{eq: positive probability for a cutpoint}
	\mathbb{P}[\log\Delta(X_0^x,X_1^x)=-t_0,\log\Delta(X_0^x,X_k^x)\leq -2t_0,\ \forall k\geq 2]\geq c.
	\end{equation}

	Write $N_{-n}=\sum_{k=0}^{\infty}\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}$.  Each time a simple random walk visits $L_n(x)$, with probability bounded below by some positive constant the simple random walk will leave $L_n(x)$ and never visit it again. Then the strong Markov property implies that 
	\begin{equation}\label{eq: strong Markov property for SRW}
	\mathbb{P}[N_{-n}\geq k]\leq (1-c)^{k-1},\,\,\forall \, k\geq1.
	\end{equation}
	Hence the upper bound in the  first part of \eqref{eq: occupation times for srw on -n slab} holds.


	Equation \eqref{eq: LLN for srw} also implies that $\tau_{-n}^x<\infty$ almost surely. The lower bound for \eqref{eq: occupation times for srw on -n slab} are straightforward since $\sum_{k=0}^{\infty}\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\geq 1$ and $\sum_{k=0}^{\infty}k\cdot \mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\geq n-1$ almost surely. 



	For $k\geq R\geq \frac{2(n+1)t_0}{-\mathbb{E}[\log\Delta(X_0,X_1)]}$, one has $-\frac{(n+1)t_0}{k}\geq -\frac{(n+1)t_0}{R}\geq \frac{1}{2}\mathbb{E}[\log\Delta(X_0,X_1)]>\mathbb{E}[\log\Delta(X_0,X_1)]$. Therefore
	for such $R$
	\begin{eqnarray*}
		\mathbb{P}[\tau_{-n}^x\geq R]&=&\mathbb{P}[\cup_{k\geq R}\{ X_{k}^x\in L_{-n}(x) \}]\leq\sum_{k\geq R}\mathbb{P}[X_{k}^x\in L_{-n}(x)]\\
		&\leq&\sum_{k\geq R}\mathbb{P}[\log\Delta(X_0^x,X_k^x)\geq (-n-1)t_0]\\
		&\leq&\sum_{k\geq R}\mathbb{P}\left[\frac{1}{k}\log\Delta(X_0^x,X_k^x)\geq -\frac{(n+1)t_0}{k}\right]\\
		&\leq&\sum_{k\geq R}\mathbb{P}\left[\frac{1}{k}\log\Delta(X_0^x,X_k^x)\geq \frac{1}{2}\mathbb{E}[\log\Delta(X_0,X_1)]\right].
	\end{eqnarray*}
	By large deviation principle (e.g.\ \cite[Theorem 2.7.7]{Durrett2010}) we know there exists constants $c_4,c_5>0$ such that 
	\begin{equation}
	\mathbb{P}\left[\frac{1}{k}\log\Delta(X_0^x,X_k^x)\geq \frac{1}{2}\mathbb{E}[\log\Delta(X_0^x,X_1^x)]\right]
	\leq c_4\exp(-c_5k),\ \forall \ k\geq1.
	\end{equation}
	Hence taking $c_3=\frac{4t_0}{-\mathbb{E}[\log\Delta(X_0,X_1)]}$, then for $n\geq0$ and $R\geq c_3(n\vee 1)\geq \frac{2(n+1)t_0}{-\mathbb{E}[\log\Delta(X_0,X_1)]}$ one has 
	\begin{equation} 
	\mathbb{P}[\tau_{-n}^x\geq R]\leq \sum_{k=c_3(n\vee1)}^{\infty} c_4\exp(-c_5k) =\frac{c_4}{1-\exp(-c_5)}\exp(-c_5c_3(n\vee 1)).
	\end{equation}
	Then \eqref{eq:tail probability for last visit time of SRW with a fixed level} holds if one takes $c_3=\frac{4t_0}{-\mathbb{E}[\log\Delta(X_0,X_1)]}$, $c_1=\frac{c_4}{1-\exp(-c_5)}$ and $c_2=c_5c_3$. 



	Notice that for $k\geq 1,j\geq c_3(n\vee 1)$, there exists  constants $c_6,c_7>0$ such that 
	\begin{equation}\label{eq: exponential decay for N_-n,tau-n large}
	\mathbb{P}[N_{-n}=k,\tau_{-n}^x=j]\leq \min\{(1-c)^{k-1},c_1\exp(-c_2j) \}\leq c_6\exp(-c_7(k+j)).
	\end{equation}
	Hence 
	\begin{eqnarray}\label{eq: tau large part}
	\sum_{k=1}^{\infty}\sum_{j=c_3(n\vee1)}^{\infty}k\cdot j\cdot \mathbb{P}[N_{-n}=k,\tau_{-n}^x=j]&\leq& c_6\sum_{k=1}^{\infty}k\exp(-c_7k)\sum_{j=1}^{\infty}j\exp(-c_7j)\nonumber\\
	&=&\frac{c_6\exp(-2c_7)}{(1-\exp(-c_7))^4}<\infty.
	\end{eqnarray}
Note 
\begin{eqnarray}\label{eq: tau small part}
\sum_{k=1}^{\infty}\sum_{j=1}^{c_3(n\vee 1)}k\cdot j\cdot \mathbb{P}[N_{-n}=k,\tau_{-n}^x=j]&\leq&
\sum_{k=1}^{\infty}\sum_{j=1}^{c_3(n\vee 1)}k\cdot c_3(n\vee 1)\cdot \mathbb{P}[N_{-n}=k,\tau_{-n}^x=j]\nonumber\\
&\leq&c_3(n\vee 1)\sum_{k=1}^{\infty}k\mathbb{P}[N_{-n}=k]\nonumber\\
&\leq &c_3(n\vee 1)\sum_{k=1}^{\infty}k(1-c)^{k-1}=\frac{c_3(n\vee 1)}{c^2}.
\end{eqnarray}

Combining \eqref{eq: tau large part} and \eqref{eq: tau small part} one has that there exists a constant $c_8>0$ such that 
\[
\mathbb{E}[N_{-n}\tau_{-n}^x]=\sum_{k=1}^{\infty}\sum_{j=1}^{\infty}k\cdot j\cdot \mathbb{P}[N_{-n}=k,\tau_{-n}^x=j]\leq c_8(n\vee 1).
\]

	Note that $\sum_{k=0}^{\infty}k\cdot\mathbf{1}_{\{X_k^x\in L_{-n}(x) \}}\leq N_{-n}\tau_{-n}^x$, whence the upper bound in the second part of    \eqref{eq: occupation times for srw on -n slab} holds.

