\label{lem: upper bound on two-point functions}
 	Recall that $\{x\leftrightarrow y \}$  denotes the event that  $x,y$ are in the same connected component of the WUSF sample $\mathfrak{F}$. Then
 	\begin{equation}\label{eq: upper bound on two-point function in WUSF}
 	\mathbb{P}[x\leftrightarrow y]\leq \sum_{m=0}^{\infty}(m+1)\mathbb{P}[X_m^x=y],

 	\end{equation}
 	where $\{X_m^x\}_{m\geq0}$ is a simple random walk on $G$ started from $x$. 

 	Let $y\in\mathfrak{T}_x$ denote the event that $y$ lies in the connected component of $x$ in the $x$-WUSF sample $\mathfrak{F}_x$.
 	Then 
 	\begin{equation}\label{eq: upper bound on two-point function in v-WUSF}
 	\mathbb{P}[y\in\mathfrak{T}_x]=\mathbb{P}[x\in\mathfrak{T}_y]\leq \sum_{m=0}^{\infty}\mathbb{P}[X_m^x=y].
 	\end{equation}

\begin{equation}\label{eq: upper bound on two-point function in WUSF}
 	\mathbb{P}[x\leftrightarrow y]\leq \sum_{m=0}^{\infty}(m+1)\mathbb{P}[X_m^x=y],

 	\end{equation}

\begin{equation}\label{eq: upper bound on two-point function in v-WUSF}
 	\mathbb{P}[y\in\mathfrak{T}_x]=\mathbb{P}[x\in\mathfrak{T}_y]\leq \sum_{m=0}^{\infty}\mathbb{P}[X_m^x=y].
 	\end{equation}

\begin{eqnarray*}
 	\mathbb{P}[x\leftrightarrow y]&\leq& \mathbb{P}[X^x \textnormal{ intersects }X^y]\\
 	&\leq& \sum_{z\in V}\sum_{m=0}^{\infty}\sum_{k=0}^{m}\mathbb{P}[X_k^x=z]\mathbb{P}[X_{m-k}^y=z]\\
 	&=& \sum_{m=0}^{\infty}\sum_{k=0}^{m}\mathbb{P}[X_m^x=y]=\sum_{m=0}^{\infty}(m+1)\mathbb{P}[X_m^x=y].
 	\end{eqnarray*}

\begin{equation}\label{eq: lower bound 1 of occupation time for S}
 \mathbb{E}\Big[\sum_{y\in L_{-n}(x)}{ \mathbf{1}_{ \{L_y(S)>0\} } }\Big]\geq c_{1}n,
 \end{equation}

\begin{equation}\label{eq: two-point fcn bigger than nonzero occupation}
 \mathbb{P}[y\leftrightarrow x]\geq \mathbb{P}[L_y(S)>0].
