\mathbb{E}\Big[\sum_{y\in L_{-n}(x)}L_y(S)\Big] 
&= & \mathbb{E}\Big[\sum_{y\in L_{-n}(x)}\sum_{w\in S}g(y,w)\Big] \nonumber\\
&=&\mathbb{E}\Big[\sum_{y\in L_{-n}(x)}\sum_{w\in S}g(w,y)\Big] \nonumber\\
&\geq&n.
 \end{eqnarray}

