\begin{equation}\label{eq: k-moment of intersection of srw with a  slab}
 	\mathbb{E}[|\{X_m^x:m\geq0 \}\cap L_n(x)|^k]\leq
 	\left\{\begin{array}{cc}
 	c^kk!\exp(-t_0n)& \textnormal{ if }\,n\geq0\\
