 	\end{array}\right..
 	\end{equation}

	Note that $\mathbb{P}[\sigma_y^x<\infty]=\mathbb{P}[\sigma_x^y<\infty]$ and
	\[
	|\{X_m^x:m\geq0 \}\cap L_n(x)|=\sum_{y\in L_n(x)}\mathbf{1}_{\{\sigma_y^x<\infty\}}.
	\]
	Hence 
	\[
	\mathbb{E}[|\{X_m^x:m\geq0 \}\cap L_n(x)|]=\mathbb{E}\Big[ \sum_{y\in L_n(x)}\mathbf{1}_{\{\sigma_x^y<\infty\}}\Big]=\mathbb{E}[|\mathfrak{T}_x\cap L_n(x)|]
	\]
	By Proposition \ref{prop: slab intersection for the x-WUSF component} one has that 
	$	\mathbb{E}[|\mathfrak{T}_x\cap L_n(x)|]	\preceq \exp(-t_0n)$
	and then
	\begin{equation}\label{eq: upper bound for prob of srw intersecting a high slab}
		\mathbb{P}[\{X_m^x:m\geq0 \}\cap L_n(x)\neq\emptyset]
		\leq 	\mathbb{E}[|\{X_m^x:m\geq0 \}\cap L_n(x)|]
		\asymp \exp(-t_0n).
	\end{equation}
	This gives the upper bound of \eqref{eq: prob of srw intersecting a high slab}.








	Write $N_n=\sum_{m=0}^{\infty}\mathbf{1}_{ \{X_m^x\in L_n(x)  \} }$ for $n\in\mathbb{Z}$ as in the proof of Corollary \ref{cor:large deviation for SRW on nonunimodular transitive graph}. Similar to \eqref{eq: strong Markov property for SRW}, by the strong Markov property of simple random walk  there exists a constant $c\in (0,1)$ such that 
	\begin{equation}\label{eq: N_n geq k conditioned on N_n big than 0}
	\mathbb{P}[N_n\geq k|N_n>0]\leq (1-c)^{k-1},k\geq 1.
	\end{equation}
	In particular,
	\begin{equation}\label{eq: k-th moments of N_n conditioned on N_n bigger than 0}
	\mathbb{E}[N_n^k|N_n>0]\leq \int_{0}^{\infty}ky^{k-1}(1-c)^{y-1}dy=\frac{1}{1-c}\cdot \frac{k!}{(-\log(1-c) )^k}
	\end{equation}

	Notice that $|\{X_m^x:m\geq0 \}\cap L_n(x)|\leq N_n$ and $\mathbb{P}[N_n>0]=\mathbb{P}[\{X_m^x:m\geq0 \}\cap L_n(x)\neq\emptyset]$.
	Therefore we have the upper bound:
	\begin{eqnarray}\label{eq: second moment for SRW intersect with a high slab}
		\mathbb{E}[|\{X_m^x:m\geq0 \}\cap L_n(x)|^2]&\leq & \mathbb{P}[N_n>0]\mathbb{E}[N_n^2|N_n>0]\stackrel{\eqref{eq: k-th moments of N_n conditioned on N_n bigger than 0}}{\preceq}\mathbb{P}[N_n>0]\nonumber\\
		&=& \mathbb{P}[\{X_m^x:m\geq0 \}\cap L_n(x)\neq\emptyset]\stackrel{\eqref{eq: upper bound for prob of srw intersecting a high slab}}{\preceq} \exp(-t_0n).
	\end{eqnarray}

	By second moment method one has the lower bound of \eqref{eq: prob of srw intersecting a high slab}, namely 
	\[
	\mathbb{P}[\{X_m^x:m\geq0 \}\cap L_n(x)\neq\emptyset]
	\geq \frac{\big(\mathbb{E}[|\{X_m^x:m\geq0 \}\cap L_n(x)|]\big)^2}{\mathbb{E}[|\{X_m^x:m\geq0 \}\cap L_n(x)|^2]}
	\stackrel{\eqref{eq: upper bound for prob of srw intersecting a high slab}, \eqref{eq: second moment for SRW intersect with a high slab}}{\succeq} \exp(-t_0n).
	\]






Hence for $n\geq 0$, by \eqref{eq: N_n geq k conditioned on N_n big than 0} and \eqref{eq: prob of srw intersecting a high slab} there exists a constant $c_1>0$ such that 
\begin{equation}\label{eq: tail probability for srw intersection with a high slab}
\mathbb{P}[|\{X_m^x:m\geq0 \}\cap L_{n}(x)|\geq k]\leq \mathbb{P}[N_n\geq k]\leq e^{-t_0n-c_1k}.
\end{equation}
	For $n\geq0$, the simple random walk $X^x$ hits every $L_{-n}(x)$ almost surely. Thus $\mathbb{P}[N_{-n}>0]=1$. Hence  by \eqref{eq: N_n geq k conditioned on N_n big than 0}
	\begin{equation}\label{eq: tail probability for srw intersection with a low slab}
	\mathbb{P}[|\{X_m^x:m\geq0 \}\cap L_{-n}(x)|\geq k]\leq \mathbb{P}[N_{-n}\geq k]\leq e^{-c_1k}.
	\end{equation}
	Recall for a nonnegative random variable $Y$ and $p>0$, $\mathbb{E}[Y^p]=\int_{0}^{\infty}py^{p-1}\mathbb{P}[Y>y]dy$ (for example see  Lemma 2.2.13 in \cite{Durrett2010}). This fact and estimates (\ref{eq: tail probability for srw intersection with a high slab}, \ref{eq: tail probability for srw intersection with a low slab}) imply \eqref{eq: k-moment of intersection of srw with a  slab}.

