S_1\preceq \sum_{j=-\infty}^{n-1}\frac{e^{t_0j}}{e^{t_0n}}+\sum_{j=n}^{0}((j-n)\vee 1)+
\sum_{j=1}^{\infty}(j-n)e^{-t_0j}\preceq|n|^2.
\end{equation}

\begin{eqnarray}\label{eq: bound S_t using holder's inequality}
S_t&\leq& \left(\sum_{j=-\infty}^{\infty}a_j^{\frac{t}{t-1}}\right)^{t-1}\cdot \sum_{j=-\infty}^{\infty}
\frac{1}{a_j^t}(|(n-j)\wedge0|\vee1)^t\big(\frac{e^{t_0j}}{e^{t_0n}}\wedge1\big)^t
\mathbb{E}|\mathfrak{F}(x,\infty)\cap L_j(x)|^t\nonumber\\
&\leq&\left(\sum_{j=-\infty}^{\infty}a_j^{\frac{t}{t-1}}\right)^{t-1}\cdot \sum_{j=-\infty}^{\infty}
\frac{1}{a_j^t}(|(n-j)\wedge0|\vee1)^t\big(\frac{e^{t_0j}}{e^{t_0n}}\wedge1\big)^t(ct)^te^{-t_0(j\vee0)},
\end{eqnarray}

\begin{equation}\label{eq: best choice of values of a_j in compact form}
a_j^{\frac{1}{t-1}}=\frac{1}{a_j}(|(n-j)\wedge0|\vee1)\big(\frac{e^{t_0j}}{e^{t_0n}}\wedge1\big)(ct)e^{-\frac{t_0(j\vee0)}{t}}=:\widetilde{b}_j,
\end{equation}

\begin{equation}\label{eq: best choice of values of a_j when n geq 0}
	a_j^{\frac{t}{t-1}}=\left\{\begin{array}{cc}
		(j-n)\cdot 1\cdot (ct)e^{-\frac{t_0j}{t}} & \textnormal{ if }j>n\\
		& \\
		1\cdot \frac{e^{t_0j}}{e^{t_0n}}\cdot (ct)e^{-\frac{t_0j}{t}} & \textnormal{ if }0\leq j\leq n\\
		& \\
		1\cdot \frac{e^{t_0j}}{e^{t_0n}}\cdot (ct) & \textnormal{ if }j<0
	\end{array}\right.
\end{equation}

\begin{equation}\label{eq: best choice of values of a_j when n less than 0}
a_j^{\frac{t}{t-1}}=\left\{\begin{array}{cc}
	(j-n)\cdot 1\cdot (ct)e^{-\frac{t_0j}{t}} & \textnormal{ if }j>0\\
	&\\
	(j-n)\cdot 1\cdot (ct) & \textnormal{ if }n<j\leq 0\\
	&\\
	1\cdot \frac{e^{t_0j}}{e^{t_0n}}\cdot (ct) & \textnormal{ if }j\leq n
\end{array}\right.
\end{equation}

\begin{eqnarray}\label{eq: bound S_t with best choice of a_j}
S_t&\leq&\left(\sum_{j=-\infty}^{\infty}a_j^{\frac{t}{t-1}}\right)^{t-1}\cdot \sum_{j=-\infty}^{\infty} \widetilde{b}_j^t\nonumber\\
&=&\left(\sum_{j=-\infty}^{\infty}a_j^{\frac{t}{t-1}}\right)^{t-1}\cdot \sum_{j=-\infty}^{\infty} a_j^{\frac{t}{t-1}}=\left(\sum_{j=-\infty}^{\infty}a_j^{\frac{t}{t-1}}\right)^{t}
\end{eqnarray}

\begin{eqnarray}\label{eq: bound of S_t when n geq 0 and t geq 2}
S_t&\leq&\left(\sum_{j=-\infty}^{-1}ct\frac{e^{t_0j}}{e^{t_0n}}+\sum_{j=1}^{n}ct\frac{e^{t_0j}}{e^{t_0n}}e^{-\frac{t_0j}{t}} +\sum_{j=n+1}^{\infty}(j-n)cte^{-\frac{t_0j}{t}} \right)^t\nonumber\\
&\leq&(ct)^t\left(\frac{c_4}{e^{t_0n}}+\frac{c_4e^{t_0(1-\frac{1}{t})n}}{e^{t_0n}(e^{t_0(1-\frac{1}{t})}-1)}+c_4e^{-\frac{t_0n}{t}}\int_{0}^{\infty}xe^{-\frac{t_0x}{t}}dx\right)^t\nonumber\\
&\leq&(ct)^t\left(\frac{c_4}{e^{t_0n}}+\frac{c_5}{e^{\frac{t_0n}{t}}}+c_4e^{-\frac{t_0n}{t}}\big(\frac{t}{t_0}\big)^2\right)^t\nonumber\\
&\leq&c_6^tt^{3t}e^{-t_0n}\leq c_7^t(t!)^3e^{-t_0n},
\end{eqnarray}

