\label{lem: number of paths connecting two neighbors}
	If $1\leq k\leq n+1$, then  $	|\mathscr{P}_{k,n}|\asymp  b^k$.
	 If $k\geq n+2$, then $\mathscr{P}_{k,n}=\emptyset$.

 	For a self-avoiding path $\pi=(w_0,w_1,\ldots,w_k)$ in $G$, if $\Delta(w_i,w_{i+1})=b^{-2}$, then we say the step from $w_i$ to $w_{i+1}$ is \notion{downward} 2 levels, and denote it by $w_i\stackrel{-2}{\rightarrow}w_{i+1}$. Similarly we define downward 1 level, upward 1 level and upward 2 levels. If $w_i\stackrel{-1}{\rightarrow}w_{i+1}$ or $w_i\stackrel{+1}{\rightarrow}w_{i+1}$, then the edge $e=(w_i,w_{i+1})$ is an edge in $\mathbb{T}_{b+1}$, we call it a \notion{tree} edge; if $w_i\stackrel{-2}{\rightarrow}w_{i+1}$ or $w_i\stackrel{+2}{\rightarrow}w_{i+1}$, then the edge $e=(w_i,w_{i+1})$ is an edge connecting a vertex to its grandparent, we call it a \notion{grandparent} edge.

 	The following relations are obvious:
 	\begin{itemize}
 		\item  if $w_{i-1}\stackrel{+1}{\rightarrow}w_{i}$, then $w_i$ is the parent of $w_{i-1}$;
 		\item  if $w_{i-1}\stackrel{+2}{\rightarrow}w_{i}$, then $w_i$ is the grandparent of $w_{i-1}$;
 		\item  if $w_{i-1}\stackrel{-1}{\rightarrow}w_{i}$, then $w_{i-1}$ is the parent of $w_i$;
 		\item  if $w_{i-1}\stackrel{-2}{\rightarrow}w_{i}$, then $w_{i-1}$ is the grandparent of $w_{i}$.
 	\end{itemize}


 	\begin{observation}\label{obs: 5.5 self-avoiding path after x and its parent}
 		If $\pi=(w_0,w_1,\ldots,w_k)\in\mathscr{P}_{k,n}$ has visited $x$ and its parent $x^-$ by time $i$, then the remaining part of the path $(w_{i+1},\ldots,w_k)$ must lie in the connected component of $v_1$ in the induced subgraph of $G\backslash\{x,x^-\}$. This is because $\{x,x^-\}$ is a cutset for $G$ and $\pi$ is self-avoiding. 
 	\end{observation}

 	\begin{claim}\label{claim: forms of paths}
 			A self-avoiding path $\pi=(w_0,w_1,\ldots,w_k)$ in $G$ connecting $v_0$ and $v_1$ has one of the following forms. 
 		If $k$ is even,  then exactly one of the following statements holds. See Figure \ref{fig: five classes adbee' of paths} and \ref{fig: four classes of paths cc'ff'} for an illustration of typical paths of each form.

 		\begin{itemize}
 			\item[(a)] $\pi$ has the form $w_0\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow}w_{t-1}\stackrel{-1}{\rightarrow}w_{t}\stackrel{+2}{\rightarrow}w_{t+1}\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{2t+2}$. Here $w_0=v_0$ and $w_{2t+2}=v_1$.

 			\item[(b)] $\pi$ has the form $w_0\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{t}\stackrel{-1}{\rightarrow}w_{t+1}\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow}w_{2t}$.

 			\item[(b')] $\pi$ has the form $w_0\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{t}\stackrel{-1}{\rightarrow}w_{t+1}\stackrel{+2}{\rightarrow}w_{t+2}\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow}w_{2t+2}$, where $w_{t+1}$ and $w_{t+3}$ are different children of $w_{t+2}$.

 			\item[(c)]  For some positive integers $\alpha,\beta$ such that $k=2+2\alpha+2\beta$, $\pi$ has the form 
 			$w_0\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha}\stackrel{-2}{\rightarrow}w_{\alpha+1}\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow} w_{\alpha+\beta}\stackrel{-1}{\rightarrow}w_{\alpha+\beta+1}\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha+2\beta+2}\stackrel{-2}{\rightarrow}\cdots\stackrel{-2}{\rightarrow}w_{2+2\alpha+2\beta}$, where $w_{\alpha-1}$ and $w_{\alpha+1}$ have different parents.


 			\item[(c')] For some positive integers $\alpha,\beta$ such that $k=2\alpha+2\beta$, $\pi$ has the form 
 			$w_0\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha}\stackrel{-2}{\rightarrow}w_{\alpha+1}\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow} w_{\alpha+\beta}\stackrel{-1}{\rightarrow}w_{\alpha+\beta+1}\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha+2\beta+1}\stackrel{-2}{\rightarrow}\cdots\stackrel{-2}{\rightarrow}w_{2\alpha+2\beta}$, where $w_{\alpha-1}$ and $w_{\alpha+1}$ have the same parent (e.g. $w_{\alpha+2\beta+1}$).
 		\end{itemize}


 		If $k$ is odd,  then exactly one of the following statements holds.
 		\begin{itemize}
 			\item[(d)] $\pi$ has the form $w_0\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow}w_{t}\stackrel{+1}{\rightarrow}w_{t+1}\stackrel{+2}{\rightarrow}w_{t+2}\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{2t+1}$. 

 			\item[(e)] $\pi$ has the form $w_0\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{t}\stackrel{+1}{\rightarrow}w_{t+1}\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow}w_{2t+1}$.

 			\item[(f)]  For some positive integers $\alpha,\beta$ such that $k=1+2\alpha+2\beta$, $\pi$ has the form 
 			$w_0\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha}\stackrel{-2}{\rightarrow}w_{\alpha+1}\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow} w_{\alpha+\beta}\stackrel{+1}{\rightarrow}w_{\alpha+\beta+1}\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha+2\beta+1}\stackrel{-2}{\rightarrow}\cdots\stackrel{-2}{\rightarrow}w_{1+2\alpha+2\beta}$, where $w_{\alpha-1}$ and $w_{\alpha+1}$ have different parents.

 			\item[(f')] For some positive integers $\alpha,\beta$ such that $k=2\alpha+2\beta-1$, $\pi$ has the form 
 			$w_0\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha}\stackrel{-2}{\rightarrow}w_{\alpha+1}\stackrel{-2}{\rightarrow}\cdots \stackrel{-2}{\rightarrow} w_{\alpha+\beta}\stackrel{+1}{\rightarrow}w_{\alpha+\beta+1}\stackrel{+2}{\rightarrow}\cdots \stackrel{+2}{\rightarrow}w_{\alpha+2\beta}\stackrel{-2}{\rightarrow}\cdots\stackrel{-2}{\rightarrow}w_{2\alpha+2\beta-1}$, where $w_{\alpha-1}$ and $w_{\alpha+1}$ have the same parent (e.g. $w_{\alpha+2\beta}$).


 		\end{itemize}



 	\end{claim}


