In particular, if $w=[w_0,\ldots,w_k]$ is such a self-avoiding path from $o$ to $B$ with $w_0,\ldots,w_{k-1}\notin B$, then 
 \begin{equation}\label{eq: probability of a loop-erased path}
 \mu(w)=\left[\prod_{j=1}^{k}p(w_{j-1},w_j)\right]\cdot
        \left[\prod_{j=0}^{k-1}G(w_{j},B\cup A_{j-1}) \right],
 \end{equation}
 where $A_{-1}=\emptyset,A_j=\{w_0,\ldots,w_j \}$ for $j\geq 1$ (see Proposition 3.2 of \cite{Lawler2018}).

\begin{equation}\label{eq: probability of a loop-erased path}
 \mu(w)=\left[\prod_{j=1}^{k}p(w_{j-1},w_j)\right]\cdot
        \left[\prod_{j=0}^{k-1}G(w_{j},B\cup A_{j-1}) \right],
 \end{equation}

	Recall $G_n$ is the sub-graph of $G$  induced by vertices $\{x:d_{\mathbb{T}}(x,v_0)\leq n \}$. Let $T_n$ be a uniform spanning tree on $G_n$. 


	We will show that there exists positive constants $c_{23},c_{24}$ such that
	\begin{equation}\label{eq: exponential decay of large distance in FUSF on grandparent graph}
	\mathbb{P}[d_{{T}_n}(v_0,v_1)\geq k]\leq  c_{24}\exp{(-c_{23}k)}.
	\end{equation}

	Start a simple random walk on $G_n$ from $v_0$ and stop at the first hit of $v_1$, then loop-erase this random walk path. Then the self-avoiding path we get has the law of the path from $v_0$ to $v_1$ in $T_n$. Let $S(t)$ be the simple random walk on $G_n$, let $o$ be $v_0$ and $B=\{v_1\}$. By \eqref{eq: probability of a loop-erased path}
	\begin{equation}\label{eq: 5.3-tail prob for large distance in FUSF on grandparent graph}
	\mathbb{P}[d_{{T}_n}(v_0,v_1)\geq k]= \sum_{j=k}^{\infty}\sum_{w\in \mathscr{P}_{j,n}}{\mu (w)}. 
	\end{equation}
	By Lemma \ref{lem: number of paths connecting two neighbors}, \eqref{eq: exponential decay of large distance in FUSF on grandparent graph} holds trivially for $k\geq n+2$. In the following we assume $k\leq n+1$.


	Notice that in our case the first product in \eqref{eq: probability of a loop-erased path} equals $\prod_{j=0}^{k-1}\frac{1}{\textnormal{deg}_{G_n}(w_j)}$, which is again symmetric for $w_0,\ldots,w_{k-1}$. Hence by Proposition \ref{prop: symmetry about ordering}, we have $\mu(w)$ is a symmetric function of $w_0,\ldots,w_{k-1}$. Using the connection between effective resistance and Green function (see Proposition 2.1 of \cite{LP2016}) one has that 
	for any reordering $w_0',\ldots,w_{k-1}'$ of $w_0,\ldots,w_{k-1}$ 
	\begin{equation}\label{eq: probability of a self-avoiding path in terms of resistance}
	\mu(w)=\prod_{j=0}^{k-1}\mathscr{R}(w_j'\leftrightarrow B\cup A_{j-1}'),
	\end{equation}
	where $A_{-1}'=\emptyset$, $A_j'=\{w_0',\ldots,w_j'\}$ and $\mathscr{R}(w_j'\leftrightarrow B\cup A_{j-1}')$ is the effective resistance from $w_j'$ to $B\cup A_{j-1}'$ in $G_n$. 


For $w=(w_0,\ldots,w_k)\in\mathscr{P}_{k,n} $, since $w$ has one of the forms listed in the proof of Lemma \ref{lem: number of paths connecting two neighbors}, using a case by case analysis it is easy to see that we can reorder $w_0,\ldots,w_{k-1}$ as $w_0',\ldots,w_{k-1}'$ such that except at most $8$ $j'$s in $\{0,\ldots,k-1\}$, one has $w_{j-2}',w_{j-1}'$ are the grandparent and parent of $w_j'$ and the grandchildren of $w_j'$ are also in $G_n$. For such an ordering and an index $j$ such that $w_{j-2}',w_{j-1}'$ are the grandparent and parent of $w_j'$ and the grandchildren of $w_j'$ are in $G_n$, one has that 
\[
\mathscr{R}(w_j'\leftrightarrow B\cup A_{j-1}')\leq \frac{b+4}{b^2+4b+8}<\frac{1}{b}.
\]
Indeed, from the local structure one has that 
\[
\mathscr{R}(w_j'\leftrightarrow B\cup A_{j-1}')\leq 
\mathscr{R}(w_j'\leftrightarrow \{w_{j-2}',w_{j-1}'\})\stackrel{\textnormal{Fig.}\ref{fig:local estimate for resistance}}{\leq} 
\frac{1}{1+1+b\cdot\frac{1}{1+\frac{1}{1+b/2}} }=\frac{b+4}{b^2+4b+8}<\frac{1}{b}.
\]
