The proof of Proposition \ref{prop: high moments for x-component intersecting a slab} uses similar ideas and notations from the proof of \cite[Theorem 6.75]{Grimmett1999}, where  high moments of a cluster were estimated in the Bernoulli percolation case. 

Here we recall some definitions from \cite[Page 135]{Grimmett1999}.

\label{lem: skeleton map}
	Suppose $x_0,x_1,\ldots,x_k$ are (possibly non-distinct) vertices of $G$ such that $x_i\in\mathfrak{T}_{x_0}$ for $i=1,\ldots,k$. Write $\mathbf{x}=(x_0,x_1,\ldots,x_k)$. Then there is a labelled skeleton $S$ with $k+1$ exterior vertices together with  a map $\varphi_{\mathbf{x}}:V(S)\rightarrow V(G)$ such that 
	\begin{itemize}
		\item the exterior vertex with label $i$ maps to $x_i$ by $\varphi_{\mathbf{x}}$ for $i=0,1,\ldots,k$ and 
		\item the edges of $S$ correspond to edge-disjoint paths in $\mathfrak{T}_{x_0}$.
	\end{itemize}  
	Here if $(u,v)$ is an edge of $S$ such that $\varphi_{\mathbf{x}}(u)=\varphi_{\mathbf{x}}(v)$, then its corresponding path is an empty path and we use the convention that the empty path is edge disjoint with any other path. Such a map is called an \notion{admissible map}.

\label{lem: point function inequality for general k}
	Suppose $x_0,x_1,\ldots,x_k$ are (possibly non-distinct) vertices of $G$. Then 
	\begin{equation}\label{eq:  point function inequality for general k}
	\tau(x_0,x_1,\ldots,x_k)\leq \sum_S\sum_{\varphi_{\mathbf{x}}}\prod_{(u,v)\in E(S)}\tau(\varphi_{\mathbf{x}}(u),\varphi_{\mathbf{x}}(v))
	\end{equation} 
	where the first sum is over all labelled skeleton with $k+1$ exterior vertices and the second sum is over all admissible maps $\varphi_{\mathbf{x}}$ from $V(S)$ to $V(G)$.

\begin{equation}\label{eq:  point function inequality for general k}
	\tau(x_0,x_1,\ldots,x_k)\leq \sum_S\sum_{\varphi_{\mathbf{x}}}\prod_{(u,v)\in E(S)}\tau(\varphi_{\mathbf{x}}(u),\varphi_{\mathbf{x}}(v))
	\end{equation}

\begin{align*}
	\tau(x_0,x_1,\ldots,x_k)\leq \sum_S\sum_{\varphi_{\mathbf{x}}}\mathbb{P}\big[
	\varphi_{\mathbf{x}}(u)\in \mathfrak{T}_{x_0} \textnormal{ for all }u\in V(S)\textnormal{ and the paths in } \mathfrak{T}_{x_0} \textnormal{ connecting } \\
	\varphi_{\mathbf{x}}(u),\varphi_{\mathbf{x}}(v)  \textnormal{ are edge-disjoint for all }(u,v)\in E(S)
	\big]
	\end{align*}

\label{lem: A.5 in appendix}
	Use same notations as in Definition \ref{def: oriented skeleton sum}. Fix an arbitrary integer $n$.  Let
	$m(S,n,j)$ be the number of $k-1$ tuples $(l_{1},\ldots,l_{k-1})$ such that the corresponding $\vec{l}$ with $l_{u_i}=l_i,i=1,\ldots,k-1$, $l_{x_0}=0$ and $l_{x_i}=n,i=1,\ldots,k$ satisfying 
