	&\leq& \mathbb{E}\bigg[\sum_{S}\sum_{l_1,\ldots,l_{k-1}}
	\sum_{x_1,\ldots,x_k\in L_n(x)}\sum_{\varphi_{\mathbf{x}}:\varphi_{\mathbf{x}}(u_i)\in L_{l_i}(x)} \prod_{(u,v)\in E(S)}\tau(\varphi_{\mathbf{x}}(u),\varphi_{\mathbf{x}}(v))\bigg]\nonumber\\
	&\preceq& c^k\sum_{S}\sum_{l_1,\ldots,l_{k-1}}\exp(-t_0f(S,\vec{l})),
