\begin{observation}\label{obs: T_x under B_k,k'}
	Suppose  $X_n,X_n',X_n''$ have the law of the size of the $n$-th generation of ``critical"  Galton--Watson trees with first generation progeny distributions  $\textnormal{Bin}(b,\frac{1}{b})$, $\textnormal{Bin}(b-1,\frac{1}{b})$ and $\textnormal{Bin}(b-2,\frac{1}{b})$ respectively (for generation at least $2$, the progeny distribution is always $\textnormal{Bin}(b,\frac{1}{b})$.)  In particular, when $b=2$, $X_0''=1$ and $X_n''=0$ for $n\geq1$. Moreover assume all the random variables $\{X_i,X_i',X_i''\colon i=0,1,2,\ldots \}$ are independent. 

	It is easy to see from Figure \ref{fig: B_k,k'} that conditioned on the event $B_{k,k'}$, one has 
	\begin{enumerate}
		\item if $n>k+k'$, then $|T_x\cap L_n(x)|=0$;
		\item if $0\leq k<n\leq k+k'$, then $|T_x\cap L_n(x)|$ has the same distribution as $\sum_{j=n}^{k+k'}X_{j-n}'$;
		\item if $0<n\leq k\leq k+k'$, then $|T_x\cap L_n(x)|$ has the same distribution as $\sum_{j=n}^{k-1}X_{j-n}'+X_{k-n}''+\sum_{j=k+1}^{k+k'}X_{j-n}'+\sum_{j=n}^{k-1}\widetilde{X}_{j-n}'$, where all these random variables  are independent and $\widetilde{X}_j'$ has the same distribution as $X_j'$;
		\item if $n\leq0$, then $|T_x\cap L_n(x)|$ has the same distribution as $X_{-n}+\sum_{j=1}^{k-1}X_{j-n}'+\sum_{j=k+1}^{k+k'}X_{j-n}'+X_{k-n}''+\sum_{j=n}^{k-1}\widetilde{X}_{j-n}'$, where all these random variables  are independent and $\widetilde{X}_j'$ has the same distribution as $X_j'$.
	\end{enumerate}
\end{observation}

Note that  the random variables $X_j',X_j''$ and $\widetilde{X}_j'$ can be stochastically dominated by $X_j$, which has the same law as $Z_j$ in Lemma \ref{lem: upper bound on the k-th moment of Z_n for a critical GW tree}. Also note that $B_{k,k'}$ are disjoint and $\mathbb{P}\big[\bigcup_{k,k'\geq0} B_{k,k'}\big]=1$. 

Therefore for $n>0,t\geq2$, one has that 
\begin{eqnarray}\label{eq: c18 for high moments of T_x cap L_n}
\mathbb{E}[|T_x\cap L_n(x)|^t]&=&
\sum_{k=0}^{n-1}\sum_{k'=n-k}^{\infty}\mathbb{P}[B_{k,k'}]\cdot \mathbb{E}\bigg[\Big(\sum_{j=n}^{k+k'}X_{j-n}'\Big)^t\bigg] \nonumber\\
&&+\sum_{k=n}^{\infty}\sum_{k'=0}^{\infty}\mathbb{P}[B_{k,k'}]\cdot \mathbb{E}\bigg[\Big(\sum_{j=n}^{k-1}X_{j-n}'+\sum_{j=k+1}^{k+k'}X_{j-n}'+X_{k-n}''+\sum_{j=n}^{k-1}\widetilde{X}_{j-n}'\Big)^t\bigg] \nonumber\\
&\leq &C^t\sum_{k=0}^{n-1}\sum_{k'=n-k}^{\infty}\frac{1}{b^{k+k'}}\cdot \mathbb{E}\bigg[\Big(\sum_{j=n}^{k+k'}X_{j-n}\Big)^t\bigg]\nonumber\\
&& +C^t\sum_{k=n}^{\infty}\sum_{k'=0}^{\infty}\frac{1}{b^{k+k'}}\cdot \mathbb{E}\bigg[\Big(\sum_{j=n}^{k+k'}X_{j-n}\Big)^t\bigg] \nonumber\\
&\stackrel{\eqref{eq: k-th moment of independent Z_0 plus dot to Z_m}}{\leq}& 
C^t\sum_{k=0}^{n-1}\sum_{k'=n-k}^{\infty}\frac{1}{b^{k+k'}}\cdot c^t(t!)[(k+k'-n)\vee 1]^{t}\nonumber\\
&&+C^t\sum_{k=n}^{\infty}\sum_{k'=0}^{\infty}\frac{1}{b^{k+k'}}\cdot c^t(t!)[(k+k'-n)\vee 1]^{t}\nonumber\\&\leq& c_2^t(t!)\sum_{j=0}^{\infty}(n+1)\cdot \frac{1}{b^{n+j}}\cdot (j\vee 1)^t\nonumber\\
&\leq & c_3^t(t!)^2\frac{n}{b^n}.
\end{eqnarray}
This proves the upper bound of \eqref{eq: sharp high moments for T_x intersect L_n(x) on the toy model} for $n\geq1$. The case of $n=0$ can be dealt in a similar way and we omit the details. 

Next we turn to the proof of the lower bound of \eqref{eq: stretched exponential decay for T_x intersecting with L_n(x)}. 

As mentioned earlier using a similar proof of Lemma \ref{lem: bounds on the n-th generation size of a critical GW tree bigger than square of n},  there exist constants $m_0>0,c>0$ such that  
\[
\mathbb{P}[X_m'\geq m^2]\geq e^{-cm},\,\,\forall \, m\geq m_0.
\]
Notice for different pairs of $(k,k')$, the event $B_{k,k'}$ are disjoint. Conditioned on $B_{k,k'}$ with $k+k'>n$, one has that $|T_x\cap L_n(x)|$ stochastically dominates $X_{k+k'-n}'$. Hence for $t\geq m_0^2$, one has the desired lower bound of \eqref{eq: stretched exponential decay for T_x intersecting with L_n(x)}:
\begin{eqnarray}
\mathbb{E}[|T_x\cap L_n(x)|\geq t]
&\geq&\sum_{k+k'=n+\lceil\sqrt{t}\rceil}\mathbb{P}[B_{k,k'}]\cdot \mathbb{P}\big[X_{\lceil\sqrt{t}\rceil}'\geq \lceil\sqrt{t}\rceil^2\big] \nonumber\\
&\succeq&\sum_{k+k'=n+\lceil\sqrt{t}\rceil}\frac{1}{b^{n+\lceil\sqrt{t}\rceil}}\cdot e^{-c\lceil\sqrt{t}\rceil}\nonumber\\
&\geq&\frac{(n\vee 1)}{b^{n}}\cdot e^{-c_1\sqrt{t}}
\end{eqnarray} 
For $t\in[1,m_0^2]$, taking a small constant $c_1$ would be enough.

\[
	\mathbb{P}[A_k]= \left\{
	\begin{array}{cc}
	\frac{b}{b+1}, & k=0\\
	& \\
	\frac{b-1}{b+1}\cdot\frac{1}{b^k}, & k>0.
	\end{array}
	\right.
	\]

\label{obs: T_x under B_k,k'}
	Suppose  $X_n,X_n',X_n''$ have the law of the size of the $n$-th generation of ``critical"  Galton--Watson trees with first generation progeny distributions  $\textnormal{Bin}(b,\frac{1}{b})$, $\textnormal{Bin}(b-1,\frac{1}{b})$ and $\textnormal{Bin}(b-2,\frac{1}{b})$ respectively (for generation at least $2$, the progeny distribution is always $\textnormal{Bin}(b,\frac{1}{b})$.)  In particular, when $b=2$, $X_0''=1$ and $X_n''=0$ for $n\geq1$. Moreover assume all the random variables $\{X_i,X_i',X_i''\colon i=0,1,2,\ldots \}$ are independent. 

	It is easy to see from Figure \ref{fig: B_k,k'} that conditioned on the event $B_{k,k'}$, one has 
	\begin{enumerate}
		\item if $n>k+k'$, then $|T_x\cap L_n(x)|=0$;
		\item if $0\leq k<n\leq k+k'$, then $|T_x\cap L_n(x)|$ has the same distribution as $\sum_{j=n}^{k+k'}X_{j-n}'$;
		\item if $0<n\leq k\leq k+k'$, then $|T_x\cap L_n(x)|$ has the same distribution as $\sum_{j=n}^{k-1}X_{j-n}'+X_{k-n}''+\sum_{j=k+1}^{k+k'}X_{j-n}'+\sum_{j=n}^{k-1}\widetilde{X}_{j-n}'$, where all these random variables  are independent and $\widetilde{X}_j'$ has the same distribution as $X_j'$;
		\item if $n\leq0$, then $|T_x\cap L_n(x)|$ has the same distribution as $X_{-n}+\sum_{j=1}^{k-1}X_{j-n}'+\sum_{j=k+1}^{k+k'}X_{j-n}'+X_{k-n}''+\sum_{j=n}^{k-1}\widetilde{X}_{j-n}'$, where all these random variables  are independent and $\widetilde{X}_j'$ has the same distribution as $X_j'$.
	\end{enumerate}

\begin{eqnarray}
\mathbb{E}[|T_x\cap L_n(x)|\geq t]
&\geq&\sum_{k+k'=n+\lceil\sqrt{t}\rceil}\mathbb{P}[B_{k,k'}]\cdot \mathbb{P}\big[X_{\lceil\sqrt{t}\rceil}'\geq \lceil\sqrt{t}\rceil^2\big] \nonumber\\
&\succeq&\sum_{k+k'=n+\lceil\sqrt{t}\rceil}\frac{1}{b^{n+\lceil\sqrt{t}\rceil}}\cdot e^{-c\lceil\sqrt{t}\rceil}\nonumber\\
&\geq&\frac{(n\vee 1)}{b^{n}}\cdot e^{-c_1\sqrt{t}}
\end{eqnarray}

\label{prop: sharp high moments for T_x intersect L_-n(x) on the toy model}
